using System;using System.Globalization;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.TextFormatting;
namespace MDNote {internal sealed class GutterTextLayout:IDisposable {
TextFormatter formatter;public void Dispose(){if(formatter!=null){formatter.Dispose();formatter=null;}}
sealed class RunStyle:TextRunProperties {readonly TextBox editor;internal RunStyle(TextBox value){editor=value;}public override Typeface Typeface {get{return new Typeface(editor.FontFamily,editor.FontStyle,editor.FontWeight,editor.FontStretch);}}public override double FontRenderingEmSize {get{return editor.FontSize;}}public override double FontHintingEmSize {get{return editor.FontSize;}}public override TextDecorationCollection TextDecorations {get{return null;}}public override Brush ForegroundBrush {get{return Brushes.Black;}}public override Brush BackgroundBrush {get{return null;}}public override CultureInfo CultureInfo {get{return CultureInfo.CurrentCulture;}}public override TextEffectCollection TextEffects {get{return null;}}}
sealed class ParagraphStyle:TextParagraphProperties {readonly TextBox editor;readonly TextRunProperties run;internal ParagraphStyle(TextBox value){editor=value;run=new RunStyle(value);}public override FlowDirection FlowDirection {get{return editor.FlowDirection;}}public override TextAlignment TextAlignment {get{return TextAlignment.Left;}}public override double LineHeight {get{return TextBlock.GetLineHeight(editor);}}public override bool FirstLineInParagraph {get{return true;}}public override TextRunProperties DefaultTextRunProperties {get{return run;}}public override TextWrapping TextWrapping {get{return editor.TextWrapping;}}public override TextMarkerProperties TextMarkerProperties {get{return null;}}public override double Indent {get{return 0;}}}
sealed class Source:TextSource {readonly string value;readonly TextRunProperties properties;internal Source(string text,TextRunProperties style){value=text;properties=style;}public override TextRun GetTextRun(int index){return index>=value.Length?(TextRun)new TextEndOfParagraph(1):new TextCharacters(value,index,value.Length-index,properties);}public override TextSpan<CultureSpecificCharacterBufferRange> GetPrecedingText(int limit){int count=Math.Min(limit,value.Length);return new TextSpan<CultureSpecificCharacterBufferRange>(count,new CultureSpecificCharacterBufferRange(CultureInfo.CurrentCulture,new CharacterBufferRange(value,0,count)));}public override int GetTextEffectCharacterIndexFromTextSourceCharacterIndex(int index){return index;}}
internal int Count(string text,TextBox editor,double width){var style=new ParagraphStyle(editor);var source=new Source(text,style.DefaultTextRunProperties);int offset=0,count=0;TextLineBreak previous=null;if(formatter==null)formatter=TextFormatter.Create(TextFormattingMode.Ideal);try{while(offset<text.Length){using(var line=formatter.FormatLine(source,offset,width,style,previous)){if(previous!=null)previous.Dispose();previous=line.GetTextLineBreak();offset+=Math.Max(1,line.Length);count++;}}}finally{if(previous!=null)previous.Dispose();}return Math.Max(1,count);}
}}
